/** DPR clamped to 2, plus pinch zoom, bounded by the context's texture limits and a pixel budget. */
function getCanvasPixelRatio(
  element: HTMLElement,
  context?: WebGLRenderingContext | WebGL2RenderingContext,
): number {
  const scale = window.visualViewport?.scale || 1;
  const requested = Math.min(window.devicePixelRatio || 1, 2) * scale;
  const width = Math.max(element.clientWidth, 1);
  const height = Math.max(element.clientHeight, 1);

  let maxDimension = 8192;
  if (context) {
    let limit = textureLimits.get(context);
    if (limit === undefined) {
      limit = Math.min(
        maxDimension,
        context.getParameter(context.MAX_TEXTURE_SIZE) as number,
        context.getParameter(context.MAX_RENDERBUFFER_SIZE) as number,
      );
      textureLimits.set(context, limit);
    }
    maxDimension = limit;
  }

  return Math.min(
    requested,
    maxDimension / Math.max(width, height),
    Math.sqrt(16_777_216 / (width * height)),
