type HtmlInCanvasElement = HTMLCanvasElement & {
  updateElementGeometry?: (element: Element, options: { canvasTransform: DOMMatrix }) => void;
};

type Box = { x: number; y: number; w: number; h: number };

type DrawOptions = {
  /** Where to land the capture, in canvas pixels. Defaults to the origin. */
  x?: number;
  y?: number;
  /** Pixel size to draw at. Defaults to the element's own box. */
  width?: number;
  height?: number;
  /** 0..1, applied as globalAlpha. */
  alpha?: number;
  /** Gaussian radius in canvas pixels, applied as ctx.filter. */
  blur?: number;
