/** Capture pixels and keep the native DOM hit-test region aligned with them. */
function drawHtmlInCanvas(
  source: HTMLCanvasElement,
  context: CanvasRenderingContext2D,
  content: Element,
  options: DrawOptions = {},
): boolean {
  const drawable = context as HtmlInCanvasContext;
  if (typeof drawable.drawElementImage !== "function") return false;

  const alpha = options.alpha ?? 1;
  if (alpha <= 0.001) return true;
